// src/components/Logo/Logo.tsx
import { jsx as jsx2 } from "react/jsx-runtime";
var DEFAULT_SVG = colored_simple_logo_default;
var SOURCES = {
  color: { brain: brain_colored_default, simple: colored_simple_logo_default, description: colored_logo_with_description_default, full: full_logo_default },
  black: {
    brain: black_logo_brain_default,
    simple: black_logo_simple_default,
    description: black_logo_with_description_default,
    lockup: black_logo_lockup_default,
    mark: black_logo_mark_default
  },
  white: {
    brain: white_logo_brain_default,
    simple: white_logo_simple_default,
    description: white_logo_with_description_default,
    lockup: white_logo_lockup_default,
    mark: white_logo_mark_default
  },
  current: { lockup: current_logo_lockup_default, mark: current_logo_mark_default }
};
